-- Hosbah queries.

-- name: ListSchedulesOfApp :many
-- Team scope: an app's schedules, by name.
SELECT * FROM schedules WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') ORDER BY name, id;

-- name: ScheduleOfApp :one
-- Team scope: one schedule of an app, by id or by name.
SELECT * FROM schedules
WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') AND (id = sqlc.arg('ref')::text OR name = sqlc.arg('ref')::text)
ORDER BY (id = sqlc.arg('ref')::text) DESC LIMIT 1;

-- name: CountSchedulesOfApp :one
SELECT count(*) FROM schedules WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id');

-- name: InsertSchedule :one
INSERT INTO schedules (team_id, app_id, name, cron, timezone, command, timeout_seconds, enabled, overlap, next_run_at)
VALUES (sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('name'), sqlc.arg('cron'), sqlc.arg('timezone'), sqlc.arg('command'),
    sqlc.arg('timeout_seconds'), sqlc.arg('enabled'), 'skip', sqlc.narg('next_run_at'))
RETURNING *;

-- name: UpdateScheduleInTeam :one
-- Team scope: the settings of a schedule. next_run_at is recomputed by the caller (null while disabled).
UPDATE schedules SET name = sqlc.arg('name'), cron = sqlc.arg('cron'), timezone = sqlc.arg('timezone'), command = sqlc.arg('command'),
    timeout_seconds = sqlc.arg('timeout_seconds'), enabled = sqlc.arg('enabled'), next_run_at = sqlc.narg('next_run_at'), updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id')
RETURNING *;

-- name: DeleteScheduleInTeam :execrows
DELETE FROM schedules WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: ClaimDueSchedules :many
-- Scheduler (system scope): the enabled schedules that are due, locked for this transaction and
-- skipping the ones another instance holds. The scheduler moves next_run_at on in the SAME
-- transaction (AdvanceSchedule), before anything runs.
SELECT * FROM schedules
WHERE enabled AND next_run_at IS NOT NULL AND next_run_at <= sqlc.arg('now')::timestamptz
ORDER BY next_run_at
LIMIT sqlc.arg('lim')
FOR UPDATE SKIP LOCKED;

-- name: AdvanceSchedule :exec
-- Scheduler (system scope): the fire time after this one (null: the expression never fires again).
UPDATE schedules SET next_run_at = sqlc.narg('next_run_at') WHERE id = sqlc.arg('id');

-- name: LockSchedule :one
-- Scheduler (system + team scope): the schedule as it is now, locked while a run is created, so
-- two fires of one schedule never both see that nothing is running.
SELECT * FROM schedules WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id') FOR UPDATE;

-- name: RecordScheduleRun :exec
-- The schedule mirrors its newest run.
UPDATE schedules SET last_run_at = sqlc.arg('last_run_at')::timestamptz, last_status = sqlc.arg('last_status')::text, updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: RecordScheduleStatus :exec
-- A run finished: the schedule shows its status if it is still the newest run.
UPDATE schedules s SET last_status = sqlc.arg('last_status')::text, updated_at = now()
WHERE s.id = sqlc.arg('id') AND s.team_id = sqlc.arg('team_id')
  AND NOT EXISTS (SELECT 1 FROM schedule_runs r WHERE r.schedule_id = s.id AND r.team_id = s.team_id
      AND r.id <> sqlc.arg('run_id')::text AND r.started_at > sqlc.arg('started_at')::timestamptz);
